package org.weftkit.wiring.runtime.registry;

import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;

/**
 * The wiring data generated by the weftkit processor and consumed by {@link WeftLoader}. Product
 * and binding maps are nested by qualifier, with the empty string for unqualified entries. All
 * returned collections must be immutable.
 */
public interface ComponentRegistry {

    List<Class<?>> loadOrder();

    Set<Class<?>> lazySingletons();

    /**
     * Maps a component to the initializer components of its required static holders, created
     * before the component itself is built. Defaults to empty for hand-built registries.
     */
    default Map<Class<?>, List<Class<?>>> requirements() {
        return Map.of();
    }

    /**
     * The {@code @WeftModule} component classes woven into this registry, in load order. Defaults
     * to empty for hand-built registries.
     */
    default List<Class<?>> modules() {
        return List.of();
    }

    /**
     * Maps every {@code @FeatureFlag} component to its flag, letting the runtime gate without an
     * annotation lookup. Defaults to empty for hand-built registries, leaving every component on.
     */
    default Map<Class<?>, Flag> featureFlags() {
        return Map.of();
    }

    Map<Class<?>, List<Dependency>> parameters();

    Map<Class<?>, Function<Object[], Object>> factories();

    Map<Class<?>, Map<String, Class<?>>> productOwners();

    Map<Class<?>, Map<String, Function<Object, Object>>> productGetters();

    Map<Class<?>, Map<String, Class<?>>> bindings();
}
